<?php
namespace App\Controllers;
use App\Core\{Controller,Database,Auth,Request};
final class SearchController extends Controller {
    public function index():void{$q=trim((string)Request::input('q'));$results=[];if($q!==''){$db=Database::connection();$t=Auth::tenantId();$like='%'.$q.'%';$defs=[['Customer','customers','id','name','customer_code','/customers'],['Job','jobs','id','job_number','description','/jobs/'],['Invoice','invoices','id','invoice_number','status','/invoices/'],['Quotation','quotations','id','quotation_number','status','/quotations/'],['Asset','customer_assets','id','asset_code','serial_number','/manage/customer-assets'],['Contract','contracts','id','contract_number','status','/manage/contracts'],['Item','items','id','item_name','sku','/inventory']];foreach($defs as [$type,$table,$id,$title,$sub,$url]){$soft=in_array($table,['customers','jobs','invoices','quotations','customer_assets','contracts','items'],true)?' AND deleted_at IS NULL':'';$s=$db->prepare("SELECT {$id} id,{$title} title,{$sub} subtitle FROM {$table} WHERE tenant_id=? {$soft} AND (CAST({$title} AS CHAR) LIKE ? OR CAST({$sub} AS CHAR) LIKE ?) LIMIT 10");$s->execute([$t,$like,$like]);foreach($s->fetchAll() as $r){$r['type']=$type;$r['url']=str_ends_with($url,'/')?$url.$r['id']:$url;$results[]=$r;}}}$this->view('search/index',['title'=>'Global Search','query'=>$q,'results'=>$results]);}
}
